   },
   {
    "outcome": "transferred",
    "reason": "TRH",
    "when": "human requested; transferred to queue `general`; call transferred to a human agent at the customer's request (queue general)"
   },
   {
    "outcome": "promise",
    "reason": "PRM",
    "when": "at least one promise recorded and no transfer afterwards; at least one promise recorded on this call, and no transfer afterwards; at least one promise recorded and no transfer followed, regardless of notes"
   },
   {
    "outcome": "no_promise",
    "reason": "HSHP",
    "when": "hardship disclosed; customer declined the customer care transfer; most serious note is hardship"
   },
